def nom_relatif(nom):
    from pathlib import PurePosixPath
    if not isinstance(nom,str) or not nom or chr(92) in nom or chr(0) in nom:raise ValueError('nom invalide')
    p=PurePosixPath(nom)
    if p.is_absolute() or '..' in p.parts or not p.parts:raise ValueError('sortie interdite')
    return str(p)

exercise.check:
assert nom_relatif('notes/a.txt')=='notes/a.txt'
for raw in ['../a','/a','','a\\b']:
    try:nom_relatif(raw)
    except ValueError:pass
    else:raise AssertionError('chemin interdit accepté')
for raw in ['a'+chr(92)+'b',chr(0)]:
    try:nom_relatif(raw)
    except ValueError:pass
    else:raise AssertionError('caractère interdit accepté')
